script.lang:
ALTER TABLE amp_indicator_disaggregation_values
ADD COLUMN IF NOT EXISTS third_category_id BIGINT REFERENCES amp_category_value(id);

CREATE INDEX IF NOT EXISTS amp_ind_disagg_values_third_category_idx
ON amp_indicator_disaggregation_values (third_category_id);

INSERT INTO amp_columns (columnid, columnname, aliasname, celltype, extractorview)
SELECT nextval('amp_columns_seq'), 'Indicator Disaggregation Level 2', NULL,
    'org.dgfoundation.amp.ar.cell.TextCell', 'v_empty_text_column'
WHERE NOT EXISTS (
    SELECT 1 FROM amp_columns WHERE columnname = 'Indicator Disaggregation Level 2'
);

UPDATE amp_global_settings SET settingsvalue = 'true'
WHERE settingsname = 'Recreate the views on the next server restart';
